  steps: { cs: ['Sesbírejte alespoň 30 párů hodnot', 'X = možná příčina, Y = výsledek', 'Vykreslete body', 'Proložte trend a spočítejte r a R²', 'Interpretujte – pozor, korelace ≠ kauzalita'],
           en: ['Collect at least 30 pairs', 'X = possible cause, Y = result', 'Plot the points', 'Fit a trend line and compute r and R²', 'Interpret – remember, correlation ≠ causation'] },
  tips: { cs: ['|r| > 0,7 silný, 0,3–0,7 střední, < 0,3 slabý vztah', 'Hledejte odlehlé body a jejich příčinu', 'Nelineární vztah může mít nízké r'],
          en: ['|r| > 0.7 strong, 0.3–0.7 moderate, < 0.3 weak', 'Look for outliers and their cause', 'A non-linear relation can show a low r'] },
